43d\u0443\u0432\u0430\u043b\u044c\u043d\u0438\u043c\u0438 \u0434\u0456\u043b\u044f\u043d\u043a\u0430\u043c\u0438 \u0434\u043e \u0432\u0435\u0440\u0448\u0438\u043d\u0438. 2,2 \u043a\u043c \u0456 1 \u0433\u043e\u0434 7 \u0445\u0432 \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u044c \u0441\u043f\u0443\u0441\u043a \u0430\u0431\u043e \u043f\u0456\u0434\u0439\u043e\u043c\u043d\u0438\u043a.","notes":"\u0426\u0435 \u043d\u0435 \u043f\u0456\u0434\u0445\u0456\u0434 \u0456\u0437 Kasina Wielka. PTTK \u043f\u0443\u0431\u043b\u0456\u043a\u0443\u0454 \u043f\u043e\u043f\u0435\u0440\u0435\u0434\u0436\u0435\u043d\u043d\u044f \u0449\u043e\u0434\u043e \u0434\u0456\u043b\u044f\u043d\u043a\u0438 Kasina Wielka\u2013\u0432\u0435\u0440\u0445\u043d\u044f \u0441\u0442\u0430\u043d\u0446\u0456\u044f \u043f\u0456\u0434\u0439\u043e\u043c\u043d\u0438\u043a\u0430; \u0432\u043e\u043d\u0430 \u043d\u0435 \u0432\u0445\u043e\u0434\u0438\u0442\u044c \u0434\u043e \u0446\u044c\u043e\u0433\u043e GPX. \u041f\u0435\u0440\u0435\u0434 \u0432\u0438\u0445\u043e\u0434\u043e\u043c \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0430\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u0456 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f."},"zh":{"name":"\u015anie\u017cnica\uff1a\u4eceGruszowiec\u4e0a\u5c71","description":"\u4eceGruszowiec\u5355\u7a0b\u4e0a\u5c71\uff0c\u5148\u8d70\u84dd\u7eff\u5171\u7ebf\u6b65\u9053\uff0c\u518d\u6cbf\u84dd\u8272\u6b65\u9053\u53ca\u77ed\u8fde\u63a5\u6bb5\u5230\u9876\u3002\u6240\u52172.2\u516c\u91cc\u53ca1\u5c0f\u65f67\u5206\u949f\u4e0d\u542b\u4e0b\u5c71\u6216\u7f06\u6905\u884c\u7a0b\u3002","notes":"\u672c\u8def\u7ebf\u4e0d\u662fKasina Wielka\u65b9\u5411\u3002PTTK\u5bf9Kasina Wielka\u81f3\u7f06\u6905\u4e0a\u7ad9\u8def\u6bb5\u53d1\u5e03\u4e86\u9650\u5236\u516c\u544a\uff0c\u8be5\u8def\u6bb5\u4e0d\u5728\u6b64GPX\u5185\u3002\u51fa\u53d1\u524d\u8bf7\u67e5\u770b\u6700\u65b0\u901a\u77e5\u3002"}},"distance_source_url":"https://mapa-turystyczna.pl/route