43d\u0447\u0443\u0454\u0442\u044c\u0441\u044f \u043d\u0430 \u0432\u0435\u0440\u0448\u0438\u043d\u0456; \u0432\u0456\u0434\u0433\u0430\u043b\u0443\u0436\u0435\u043d\u043d\u044f \u0434\u043e \u043f\u0440\u0438\u0442\u0443\u043b\u043a\u0443 \u0442\u0430 \u0441\u043f\u0443\u0441\u043a \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u0456.","notes":"\u041d\u0435 \u043f\u043b\u0443\u0442\u0430\u0439\u0442\u0435 \u0432\u0435\u0440\u0448\u0438\u043d\u0443 Leskowiec \u0437 \u043f\u0440\u0438\u0442\u0443\u043b\u043a\u043e\u043c \u043f\u0456\u0434 Gro\u0144 Jana Paw\u0142a II. \u0427\u0430\u0441 \u043e\u0440\u0456\u0454\u043d\u0442\u043e\u0432\u043d\u0438\u0439: \u0432\u0440\u0430\u0445\u0443\u0439\u0442\u0435 \u0432\u0456\u0434\u043f\u043e\u0447\u0438\u043d\u043e\u043a, \u043f\u043e\u0433\u043e\u0434\u0443 \u0442\u0430 \u043f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u043d\u044f."},"zh":{"name":"Leskowiec\uff1a\u4eceRzyki Mydlarze\u4e0a\u5c71","description":"\u4eceRzyki, Mydlarze\u7ad9\u6cbf\u9ed1\u8272\u6b65\u9053\u5230Prze\u0142\u0119cz W\u0142adys\u0142awa Midowicza\uff0c\u518d\u6cbf\u7ea2\u9ec4\u5171\u7ebf\u6b65\u9053\u767bLeskowiec\u30022.5\u516c\u91cc\u8def\u7ebf\u7ec8\u70b9\u4e3a\u5c71\u9876\uff0c\u4e0d\u542b\u524d\u5f80\u5c71\u5c4b\u7684\u652f\u7ebf\u6216\u4e0b\u5c71\u3002","notes":"\u8bf7\u533a\u5206Leskowiec\u5c71\u9876\u4e0eGro\u0144 Jana Paw\u0142a II\u4e0b\u65b9\u7684\u5c71\u5c4b\u3002\u65f6\u95f4\u4e3a\u4f30\u7b97\uff0c\u8bf7\u8ba1\u5165\u4f11\u606f\u3001\u5929\u6c14\u53ca\u8fd4\u7a0b\u3002"}},"distance_source_url":"https://mapa-turystyczna.pl/route/3npty","distance_verified_at":"2026-11-22T00:00:00Z","elevation_gain_source_url":"https://mapa-turystyczna.pl/route/3npty","elevation_gain_verified_at":"2026-11-22T00:00:00Z","time_source_url":"https://mapa-turystyczna.pl/route/3npty","time_verified_at":"2026-11-22T00:00:00Z"}},{"kind":"poi","body":{"peak_slug":"lysina","trail_id":null,"type_slug":"shelter","latitude":49.782289,"longitude":20.022684,"active":true,"source_url":"https://malopolska.szlaki.pttk.pl/2531-pttk-malopolska-schronisko-pttk-na-kudlaczach","last_verified_at":"2026-11-22T00:00:00Z","website_url":null,"google_maps_url":"https://www.google.com/maps/search/?api=1&query=49.782289,20.022684","i18n":{"pl":{"name":"Schronisko PTTK na Kud\u0142aczach","description":"Schronisko w rejonie Kud\u0142aczy, przy przebiegu wybranej trasy z Pcimia na \u0141ysin\u0119. Aktualne godziny i dost\u0119pno\u015b\u0107 us\u0142ug potwierd\u017a u gospodarza.","tips":null},"en":{"name":"PTTK hut on Kud\u0142acze","description":"Mountain hut in the Kud\u0142acze area, beside the selected Pcim\u2013\u0141ysina route. Confirm current hours and service availability with the operator.","tips":null},"ua":{"name":"\u041f\u0440\u0438\u0442\u0443\u043b\u043e\u043a PTTK \u043d\u0430 Kud\u0142acze","description":"\u041f\u0440\u0438\u0442\u0443\u043b\u043e\u043a \u0443 \u0440\u0430\u0439\u043e\u043d\u0456 Kud\u0142acze \u0431\u0456\u043b\u044f \u0432\u0438\u0431\u0440\u0430\u043d\u043e\u0433\u043e \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0443 Pcim\u2013\u0141ysina. \u041f\u043e\u0442\u043e\u0447\u043d\u0456 \u0433\u043e\u0434\u0438\u043d\u0438 \u0442\u0430 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0456\u0441\u0442\u044c \u043f\u043e\u0441\u043b\u0443\u0433 \u0443\u0442\u043e\u0447\u043d\u044e\u0439\u0442\u0435 \u0443 \u0433\u043e\u0441\u043f\u043e\u0434\u0430\u0440\u044f.","tips":null},"zh":{"name":"Kud\u0142acze\u7684PTTK\u5c71\u5c4b","description":"\u4f4d\u4e8eKud\u0142acze\u5730\u533a\uff0c\u9760\u8fd1\u6240\u9009Pcim\u81f3\u0141ysina\u8def\u7ebf\u3002\u8425\u4e1a\u65f6\u95f4\u53ca\u670d\u52a1\u662f\u5426\u53ef\u7528\uff0c\u8bf7\u5411\u7ecf\u8425\u8005\u786e\u8ba4\u3002","tips":null}}}},{"kind":"poi","body":{"peak_slug":"snieznica","trail_id":null,"type_slug":"shelter","latitude":49.708218,"longitude":20.173573,"active":true,"source_url":"https://malopolska.szlaki.pttk.pl/1517-pttk-malopolska-mlodziezowy-osrodek-rekolekcyjny-i-schronisko-pod-snieznica","last_verified_at":"2026-11-22T00:00:00Z","website_url":null,"google_maps_url":"https://www.google.com/maps/search/?api=1&query=49.708218,20.173573","i18n":{"pl":{"name":"O\u015brodek i schronisko pod \u015anie\u017cnic\u0105","description":"O\u015brodek ze schroniskiem i kaplic\u0105 na po\u0142udniowo-zachodnim zboczu \u015anie\u017cnicy. Le\u017cy poza wybranym niebieskim podej\u015bciem; doj\u015bcie nie jest wliczone do GPX ani parametr\u00f3w trasy.","tips":null},"en":{"name":"Retreat centre and hut below \u015anie\u017cnica","description":"Centre with a hut and chapel on the south-western slope of \u015anie\u017cnica. It is off the selected blue approach; its detour is not included in the GPX or route figures.","tips":null},"ua":{"name":"\u0426\u0435\u043d\u0442\u0440 \u0432\u0456\u0434\u043f\u043e\u0447\u0438\u043d\u043a\u0443 \u0442\u0430 \u043f\u0440\u0438\u0442\u0443\u043b\u043e\u043a \u043f\u0456\u0434 \u015anie\u017cnica","description":"\u0426\u0435\u043d\u0442\u0440 \u0456\u0437 \u043f\u0440\u0438\u0442\u0443\u043b\u043a\u043e\u043c \u0456 \u043a\u0430\u043f\u043b\u0438\u0446\u0435\u044e \u043d\u0430 \u043f\u0456\u0432\u0434\u0435\u043d\u043d\u043e-\u0437\u0430\u0445\u0456\u0434\u043d\u043e\u043c\u0443 \u0441\u0445\u0438\u043b\u0456 \u015anie\u017cnica. \u0412\u0456\u043d \u0440\u043e\u0437\u0442\u0430\u0448\u043e\u0432\u0430\u043d\u0438\u0439 \u043f\u043e\u0437\u0430 \u0432\u0438\u0431\u0440\u0430\u043d\u0438\u043c \u0441\u0438\u043d\u0456\u043c \u043f\u0456\u0434\u0445\u043e\u0434\u043e\u043c; \u0432\u0456\u0434\u0433\u0430\u043b\u0443\u0436\u0435\u043d\u043d\u044f \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u0435 \u0434\u043e GPX \u0447\u0438 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0456\u0432 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0443.","tips":null},"zh":{"name":"\u015anie\u017cnica\u5c71\u4e0b\u7684\u8425\u5730\u53ca\u5c71\u5c4b","description":"\u4f4d\u4e8e\u015anie\u017cnica\u897f\u5357\u5761\uff0c\u8bbe\u6709\u5c71\u5c4b\u53ca\u5c0f\u6559\u5802\u3002\u5176\u4f4d\u7f6e\u4e0d\u5728\u6240\u9009\u84dd\u8272\u4e0a\u5c71\u8def\u7ebf\u4e0a\uff0c\u524d\u5f80\u6b64\u5904\u7684\u652f\u7ebf\u672a\u8ba1\u5165GPX\u6216\u8def\u7ebf\u53c2\u6570\u3002","tips":null}}}},{"kind":"poi","body":{"peak_slug":"gora-zar","trail_id":null,"type_slug":"viewpoint","latitude":49.787187,"longitude":19.224802,"active":true,"source_url":"https://www.czernichow.com.pl/atrakcje/art-kolej-linowoterenowa-na-gorze-zar,69","last_verified_at":"2026-11-22T00:00:00Z","website_url":"https://www.pkl.pl/gora-zar","google_maps_url":"https://www.google.com/maps/search/?api=1&query=49.787187,19.224802","i18n":{"pl":{"name":"Panorama w rejonie szczytu \u017baru","description":"Rejon widokowy przy ko\u0144cu wybranej trasy pieszej, z panoram\u0105 Beskidu Ma\u0142ego i prze\u0142omu So\u0142y. Punkt nie oznacza wej\u015bcia na teren ogrodzonego zbiornika.","tips":null},"en":{"name":"Panorama near the \u017bar summit","description":"Viewpoint area at the end of the selected walking route, overlooking the Little Beskids and the So\u0142a gorge. The marker does not indicate access inside the fenced reservoir.","tips":null},"ua":{"name":"\u041f\u0430\u043d\u043e\u0440\u0430\u043c\u0430 \u0431\u0456\u043b\u044f \u0432\u0435\u0440\u0448\u0438\u043d\u0438 \u017bar","description":"\u041e\u0433\u043b\u044f\u0434\u043e\u0432\u0430 \u043c\u0456\u0441\u0446\u0435\u0432\u0456\u0441\u0442\u044c \u043d\u0430\u043f\u0440\u0438\u043a\u0456\u043d\u0446\u0456 \u0432\u0438\u0431\u0440\u0430\u043d\u043e\u0457 \u043f\u0456\u0448\u043e\u0457 \u0441\u0442\u0435\u0436\u043a\u0438 \u0437 \u043f\u0430\u043d\u043e\u0440\u0430\u043c\u043e\u044e \u041c\u0430\u043b\u0438\u0445 \u0411\u0435\u0441\u043a\u0438\u0434\u0456\u0432 \u0456 \u0443\u0449\u0435\u043b\u0438\u043d\u0438 So\u0142a. \u041f\u043e\u0437\u043d\u0430\u0447\u043a\u0430 \u043d\u0435 \u043e\u0437\u043d\u0430\u0447\u0430\u0454 \u0434\u043e\u0441\u0442\u0443\u043f \u0437\u0430 \u043e\u0433\u043e\u0440\u043e\u0436\u0443 \u0432\u043e\u0434\u043e\u0441\u0445\u043e\u0432\u0438\u0449\u0430.","tips":null},"zh":{"name":"\u017bar\u5c71\u9876\u9644\u8fd1\u5168\u666f","description":"\u6240\u9009\u6b65\u884c\u8def\u7ebf\u7ec8\u70b9\u9644\u8fd1\u7684\u89c2\u666f\u533a\u57df\uff0c\u53ef\u8fdc\u773a\u5c0f\u8d1d\u65af\u57fa\u5fb7\u5c71\u53caSo\u0142a\u6cb3\u5ce1\u8c37\u3002\u6b64\u6807\u8bb0\u4e0d\u8868\u793a\u53ef\u4ee5\u8fdb\u5165\u6c34\u5e93\u56f4\u680f\u5185\u3002","tips":null}}}},{"kind":"poi","body":{"peak_slug":"leskowiec","trail_id":null,"type_slug":"shelter","latitude":49.795338,"longitude":19.447673,"active":true,"source_url":"https://schroniska.pttk.pl/leskowiec/pl/index.html","last_verified_at":"2026-11-22T00:00:00Z","website_url":"https://schroniska.pttk.pl/leskowiec/pl/index.html","google_maps_url":"https://www.google.com/maps/search/?api=1&query=49.795338,19.447673","i18n":{"pl":{"name":"Schronisko PTTK Leskowiec","description":"Schronisko pod Groniem Jana Paw\u0142a II, odr\u0119bne od szczytu Leskowca. Wybrany GPX ko\u0144czy si\u0119 na szczycie, wi\u0119c doj\u015bcie do schroniska trzeba zaplanowa\u0107 osobno. Sprawd\u017a aktualn\u0105 ofert\u0119 u gospodarza.","tips":null},"en":{"name":"PTTK Leskowiec hut","description":"Hut below Gro\u0144 Jana Paw\u0142a II, separate from the Leskowiec summit. The selected GPX ends at the summit, so plan the hut detour separately. Check current services with the operator.","tips":null},"ua":{"name":"\u041f\u0440\u0438\u0442\u0443\u043b\u043e\u043a PTTK Leskowiec","description":"\u041f\u0440\u0438\u0442\u0443\u043b\u043e\u043a \u043f\u0456\u0434 Gro\u0144 Jana Paw\u0142a II, \u043e\u043a\u0440\u0435\u043c\u043e \u0432\u0456\u0434 \u0432\u0435\u0440\u0448\u0438\u043d\u0438 Leskowiec. \u0412\u0438\u0431\u0440\u0430\u043d\u0438\u0439 GPX \u0437\u0430\u043a\u0456\u043d\u0447\u0443\u0454\u0442\u044c\u0441\u044f \u043d\u0430 \u0432\u0435\u0440\u0448\u0438\u043d\u0456, \u0442\u043e\u0436 \u0432\u0456\u0434\u0433\u0430\u043b\u0443\u0436\u0435\u043d\u043d\u044f \u0434\u043e \u043f\u0440\u0438\u0442\u0443\u043b\u043a\u0443 \u043f\u043b\u0430\u043d\u0443\u0439\u0442\u0435 \u043e\u043a\u0440\u0435\u043c\u043e. \u041f\u043e\u0441\u043b\u0443\u0433\u0438 \u0443\u0442\u043e\u0447\u043d\u044e\u0439\u0442\u0435 \u0443 \u0433\u043e\u0441\u043f\u043e\u0434\u0430\u0440\u044f.","tips":null},"zh":{"name":"PTTK Leskowiec\u5c71\u5c4b","description":"\u5c71\u5c4b\u4f4d\u4e8eGro\u0144 Jana Paw\u0142a II\u4e0b\u65b9\uff0c\u4e0eLeskowiec\u5c71\u9876\u5e76\u975e\u540c\u4e00\u70b9\u3002\u6240\u9009GPX\u7ec8\u6b62\u4e8e\u5c71\u9876\uff0c\u524d\u5f80\u5c71\u5c4b\u987b\u53e6\u884c\u89c4\u5212\uff1b\u670d\u52a1\u60c5\u51b5\u8bf7\u5411\u7ecf\u8425\u8005\u67e5\u8be2\u3002","tips":null}}}}],"range_change":{"peak_id":69,"before":21,"after":22,"after_slug":"beskid-wyspowy"}}$manifest$::jsonb m),
expected as (select p, (select r->'body' from jsonb_array_elements(m->'records') r where r->>'kind'='trail' and r->'body'->>'peak_slug'=p->>'slug') tb,
 (select r->'body' from jsonb_array_elements(m->'records') r where r->>'kind'='poi' and r->'body'->>'peak_slug'=p->>'slug') pb
 from manifest,jsonb_array_elements(m->'peaks') p)
select e.p->>'slug' peak_slug, mr.slug range_slug,
 (select count(*) from public.trails where peak_id=p.id and active) trails,
 (select count(*) from public.pois where peak_id=p.id and active) pois,
 case when t.route_geometry is not null then 1 else 0 end mapped_trails,
 (select array_agg(lang order by lang collate "C") from public.trails_i18n where trail_id=t.id) trail_languages,
 (select array_agg(lang order by lang collate "C") from public.pois_i18n where poi_id=poi.id) poi_languages,
 coalesce(p.active and not p.is_korona and p.range_id=case when p.id=69 then 22 else (e.p->>'range_id')::bigint end
 and not exists(select from unnest(array['peak_id','slug','start_point_name','end_point_name','distance_km','elevation_gain_m','time_min','difficulty','route_type','active','source_url','last_verified_at','map_url','gpx_url','distance_source_url','distance_verified_at','elevation_gain_source_url','elevation_gain_verified_at','time_source_url','time_verified_at','route_geometry','geometry_source_url','geometry_verified_at']) k where to_jsonb(t)->k is distinct from to_jsonb(jsonb_populate_record(null::public.trails,e.tb||jsonb_build_object('peak_id',p.id)))->k)
 and not exists(select from unnest(array['peak_id','trail_id','type_id','latitude','longitude','active','source_url','last_verified_at','website_url','google_maps_url']) k where to_jsonb(poi)->k is distinct from to_jsonb(jsonb_populate_record(null::public.pois,e.pb||jsonb_build_object('peak_id',p.id,'type_id',ty.id)))->k)
 and (select jsonb_object_agg(lang,jsonb_build_object('name',name,'description',description,'notes',notes)) from public.trails_i18n where trail_id=t.id)=e.tb->'i18n'
 and (select jsonb_object_agg(lang,jsonb_build_object('name',name,'description',description,'tips',tips)) from public.pois_i18n where poi_id=poi.id)=e.pb->'i18n',false) review_matches,
 exists(select from peakguide_private.catalogue_batch_receipts where batch_key='nonkgp-01') package_applied
from expected e left join public.peaks p on p.id=(e.p->>'id')::bigint and p.slug=e.p->>'slug'
left join public.mountain_ranges mr on mr.id=p.range_id
left join public.trails t on t.peak_id=p.id and t.slug=e.tb->>'slug'
left join public.poi_types ty on ty.slug=e.pb->>'type_slug'
left join public.pois poi on poi.peak_id=p.id and poi.source_url=e.pb->>'source_url' and poi.type_id=ty.id
order by e.p->>'slug';
